{
  "items": [
    {
      "name": "Polynomial.card_eq_of_natDegree_le_of_coeff_le",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ {n : ℕ} {B₁ B₂ : Fin (n + 1) → ℝ},\n  {p | p.natDegree ≤ n ∧ ∀ (i : Fin (n + 1)), B₁ i ≤ ↑(p.coeff ↑i) ∧ ↑(p.coeff ↑i) ≤ B₂ i}.ncard =\n    ∏ i, (⌊B₂ i⌋ - ⌈B₁ i⌉ + 1).toNat"
    },
    {
      "name": "MvPolynomial.cardinalMk_le_max",
      "module_name": "Mathlib.Algebra.MvPolynomial.Cardinal",
      "kind": "theorem",
      "type": "∀ {σ R : Type u} [inst : CommSemiring R],\n  Cardinal.mk (MvPolynomial σ R) ≤ max (max (Cardinal.mk R) (Cardinal.mk σ)) Cardinal.aleph0"
    },
    {
      "name": "MvPolynomial.cardinalMk_le_max_lift",
      "module_name": "Mathlib.Algebra.MvPolynomial.Cardinal",
      "kind": "theorem",
      "type": "∀ {σ : Type u} {R : Type v} [inst : CommSemiring R],\n  Cardinal.mk (MvPolynomial σ R) ≤\n    max (max (Cardinal.lift.{u, v} (Cardinal.mk R)) (Cardinal.lift.{v, u} (Cardinal.mk σ))) Cardinal.aleph0"
    },
    {
      "name": "MvPolynomial.cardinalMk_eq_max",
      "module_name": "Mathlib.Algebra.MvPolynomial.Cardinal",
      "kind": "theorem",
      "type": "∀ {σ R : Type u} [inst : CommSemiring R] [Nonempty σ] [Nontrivial R],\n  Cardinal.mk (MvPolynomial σ R) = max (max (Cardinal.mk R) (Cardinal.mk σ)) Cardinal.aleph0"
    },
    {
      "name": "MvPolynomial.cardinalMk_eq_max_lift",
      "module_name": "Mathlib.Algebra.MvPolynomial.Cardinal",
      "kind": "theorem",
      "type": "∀ {σ : Type u} {R : Type v} [inst : CommSemiring R] [Nonempty σ] [Nontrivial R],\n  Cardinal.mk (MvPolynomial σ R) =\n    max (max (Cardinal.lift.{u, v} (Cardinal.mk R)) (Cardinal.lift.{v, u} (Cardinal.mk σ))) Cardinal.aleph0"
    }
  ]
}
